// The mathematical competencies of the exercise generators: the single source of truth. Pure data, no DOM, no import
// (bank.js reads it; it must never import bank.js).
//
// The French lycée programmes name six competencies: chercher, modéliser, représenter, raisonner, calculer, communiquer.
// "Communiquer" is left out on purpose (a generated question with a short answer cannot assess it). Each generator id has
// ONE main competency (first in its list) and optional secondary ones. The filter of the automatismes page, the labels of
// the teacher's list and the coverage tables of docs/AUTOMATISMES_COMPETENCES.md all use the main competency only.
//
// How an id was classified (by reading its skill and generated instances at the three levels, not by keyword):
//   calculer    carrying out a technique: derivative, equation, limit, exact value, a four-choice item on a computation;
//   representer reading or producing a table, tree, graph, diagram, interval, or passing from one register to another;
//   modeliser   turning a described situation (evolution, random experiment, cost, optimisation, counting) into an
//               expression, equation, sequence or law, the translation being the crux;
//   raisonner   true/false with justification, find-the-error, counter-example, implication, converse, proof;
//   chercher    open task: conjecture, trial and test. Kept separate on purpose: a timed starter is not an investigation.
//               The investigations of a chapter live in its tab "Manipuler" (heading "Chercher avant de formaliser",
//               site/js/chapter-sequence.js) and in the laboratory. No generator has "chercher" as its main competency;
//               do not relabel one to fill the gap.
// A new generator needs one line here (tests/competencies.test.mjs fails otherwise and pins the coverage table).
// Classes are never listed in code: every loop goes over CLASSES and TEMPLATES of bank.js, so a new class only needs its
// lines in the table below (the class comments of the table are headings for the reader, nothing reads them).

// Definitions: the usual wording of the lycée programmes. No bulletin reference is cited here (none is recorded in
// PROJECT_BRIEF.md section 3 or docs/CURRICULUM.md); check the official text before quoting it elsewhere.
export const COMPETENCIES = [
  { id: 'chercher', label: ['Chercher', 'Investigate'], definition: ['Chercher, expérimenter, en particulier à l’aide d’outils logiciels.', 'Investigate and experiment, in particular with software tools.'] },
  { id: 'modeliser', label: ['Modéliser', 'Model'], definition: ['Modéliser, faire une simulation, valider ou invalider un modèle.', 'Model, run a simulation, validate or invalidate a model.'] },
  { id: 'representer', label: ['Représenter', 'Represent'], definition: ['Représenter, choisir un cadre (numérique, algébrique, géométrique…), changer de registre.', 'Represent, choose a setting (numerical, algebraic, geometric…), change register.'] },
  { id: 'raisonner', label: ['Raisonner', 'Reason'], definition: ['Raisonner, démontrer, trouver des résultats partiels et les mettre en perspective.', 'Reason, prove, find partial results and put them in perspective.'] },
  { id: 'calculer', label: ['Calculer', 'Calculate'], definition: ['Calculer, appliquer des techniques et mettre en œuvre des algorithmes.', 'Calculate, apply techniques and carry out algorithms.'] },
];
export const COMPETENCY_IDS = COMPETENCIES.map((c) => c.id);
export const competencyById = (id) => COMPETENCIES.find((c) => c.id === id) || null;

const H = 'chercher', M = 'modeliser', P = 'representer', R = 'raisonner', C = 'calculer';

