export const mainCompetency = (id) => COMPETENCY_OF[id]?.[0] || null;
export const secondaryCompetencies = (id) => (COMPETENCY_OF[id] || []).slice(1);
// True when the main competency of the generator is one of `list` (an empty or missing list accepts everything).
export const hasCompetency = (id, list) => !list?.length || list.includes(mainCompetency(id));

// Coverage of a list of templates ({id, cls, chapter, fast}): counts of main competencies, all and fast, per class and
// per chapter. Used by the tests (pinned table) and by the page (which competencies a class or chapter can serve).
export function coverage(templates) {
  const zero = () => Object.fromEntries(COMPETENCY_IDS.map((c) => [c, { all: 0, fast: 0 }]));
  const byClass = {}, byChapter = {};
  for (const t of templates) {
    const c = mainCompetency(t.id); if (!c) continue;
    for (const cell of [(byClass[t.cls] ||= zero())[c], (byChapter[t.chapter] ||= zero())[c]]) { cell.all++; if (t.fast) cell.fast++; }
  }
  return { byClass, byChapter };
}
